const http=require('http'),fs=require('fs'),path=require('path');
http.createServer((q,r)=>{const f=path.join(__dirname,'mystix-cockpit.html');r.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});r.end('<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body>'+fs.readFileSync(f,'utf8')+'</body></html>');}).listen(4817);
